@app.post("/safety/new")
def create_safety_item(
    item_type: str = Form(...),
    title: str = Form(...),
    event_date: str = Form(...),
    location: str = Form(""),
    activity_id: str = Form(""),
    responsible_party: str = Form(""),
    severity: str = Form("WATCH"),
    description: str = Form(...),
    corrective_action: str = Form("")
):
    pid = project_id()
    linked_activity = int(activity_id) if activity_id.strip() else None

    c = db()

    if linked_activity is not None:
        valid = c.execute(
            "SELECT id FROM activities WHERE id=? AND project_id=?",
            (linked_activity, pid)
        ).fetchone()
        if not valid:
            linked_activity = None

    c.execute(
        """
        INSERT INTO safety_items(
            project_id,
            activity_id,
            event_date,
            item_type,
            title,
            location,
            responsible_party,
            severity,
            status,
            description,
            corrective_action,
            created
        )
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?)
        """,
        (
            pid,
            linked_activity,
            event_date,
            item_type,
            title.strip(),
            location.strip(),
            responsible_party.strip(),
            severity,
            "OPEN",
            description.strip(),
            corrective_action.strip(),
            date.today().isoformat()
        )
    )

    c.commit()
    c.close()

    return RedirectResponse(url="/safety", status_code=303)


